import unreal,sys
from pathlib import Path
sys.path.insert(0,str(Path(unreal.Paths.project_dir())/'MigrationStaging'))
from combat_helpers import *
bp=asset('Interaction/BP_SurvivorInteractionCharacter')
with toolset_registry.tool_raising_exceptions():
 var(bp,'ShotIgnoreActors',unreal.Actor.static_class(),array=True);var(bp,'ShotAimPoint','Vector');var(bp,'WasPistolDrawn','bool')
 fn(bp,'CheckPistolEquip');fn(bp,'InitializePistolAnimation')
 write(bp,'InitializePistolAnimation','''(fn InitializePistolAnimation ()
 (Components|SkeletalMesh|SetAnimInstanceClass :self (Variables|Character|GetMesh) :NewClass "/Game/AIExample/Combat/Animation/ABP_SurvivorCombat.ABP_SurvivorCombat_C"))''')
 write(bp,'PerformPistolShot','''(fn PerformPistolShot (ViewOrigin ViewDirection)
 (if (Networking|HasAuthority)
  (bind Ignore (Actor|GetAllActorsOfClass :ActorClass "/Game/AIExample/Items/BP_ItemPickup.BP_ItemPickup_C"))
  (Variables|Default|SetShotIgnoreActors Ignore)
  (Utilities|Array|Add (Variables|Default|GetShotIgnoreActors) self)
  (Variables|Default|SetShotAimPoint (+ ViewOrigin (* (Math|Vector|Normalize ViewDirection) 10000.0)))
  (bind (CameraHit CameraBlocked) (Collision|LineTraceByChannel :Start ViewOrigin :End (Variables|Default|GetShotAimPoint) :TraceChannel "TraceTypeQuery1" :ActorsToIgnore (Variables|Default|GetShotIgnoreActors)))
  (bind (CB CI CT CD CL CameraImpact CN CIN CPM CA CC CHB CBn CItem CE CF CS CEnd) (Collision|BreakHitResult CameraHit))
  (if CameraBlocked (Variables|Default|SetShotAimPoint CameraImpact))
  (bind Muzzle (Transformation|GetSocketLocation :self (Variables|Default|GetSidearmVisual) :InSocketName "Muzzle"))
  (bind ShotDirection (Math|Vector|Normalize (- (Variables|Default|GetShotAimPoint) Muzzle)))
  (bind (Hit DidHit) (Collision|LineTraceByChannel :Start Muzzle :End (+ (Variables|Default|GetShotAimPoint) (* ShotDirection 2.0)) :TraceChannel "TraceTypeQuery1" :ActorsToIgnore (Variables|Default|GetShotIgnoreActors)))
  (bind (Blocking Initial Time Distance Location ImpactPoint Normal ImpactNormal PhysMat HitActor HitComponent HitBone Bone HitItem Element Face TraceStart TraceEnd) (Collision|BreakHitResult Hit))
  (Variables|Default|SetPublicHasImpact DidHit)
  (Variables|Default|SetPublicImpactLocation (select DidHit ImpactPoint (Variables|Default|GetShotAimPoint)))
  (if DidHit (Game|Damage|ApplyPointDamage :DamagedActor HitActor :BaseDamage 25.0 :HitFromDirection ShotDirection :HitInfo Hit :EventInstigator (Pawn|GetController) :DamageCauser self :DamageTypeClass "/Script/Engine.DamageType"))
  (Variables|Default|SetPublicShotSerial (+ (Variables|Default|GetPublicShotSerial) 1))))''')
 write(bp,'PlayPistolShot','''(fn PlayPistolShot ()
 (if (== (Variables|Default|GetPublicActiveSlot) 2)
  (Animation|Montage|PlaySlotAnimationasDynamicMontage :self (Components|SkeletalMesh|GetAnimInstance (Variables|Character|GetMesh)) :Asset "/Game/AIExample/Combat/Animation/Survivor_MM_Pistol_Fire.Survivor_MM_Pistol_Fire" :SlotNodeName "PistolUpperBody" :BlendInTime 0.02 :BlendOutTime 0.10 :LoopCount 1)
  (Niagara|SpawnSystemAttached :SystemTemplate "/Game/AIExample/Weapons/TheHouse/07_ParticleFX/Pistol/NS_Pistol.NS_Pistol" :AttachToComponent (Variables|Default|GetSidearmVisual) :AttachPointName "Muzzle" :LocationType "SnapToTarget" :bAutoDestroy true)
  (Audio|PlaySoundatLocation :Sound "/Game/AIExample/Weapons/TheHouse/06_SFX/GunSFX/Pistol/SC_Pistol_Fire.SC_Pistol_Fire" :Location (Transformation|GetSocketLocation :self (Variables|Default|GetSidearmVisual) :InSocketName "Muzzle") :AttenuationSettings "/Game/AIExample/Combat/SA_Pistol.SA_Pistol" :OwningActor self)
  (if (Pawn|IsLocallyControlled)
   (Pawn|Input|AddControllerPitchInput :Val -0.65)
   (Pawn|Input|AddControllerYawInput :Val (Math|Random|RandomFloatinRange -0.15 0.15)))))''')
 write(bp,'RefreshPistolReload','''(fn RefreshPistolReload ()
 (if (Variables|Default|GetPublicReloading)
  (Animation|Montage|PlaySlotAnimationasDynamicMontage :self (Components|SkeletalMesh|GetAnimInstance (Variables|Character|GetMesh)) :Asset "/Game/AIExample/Combat/Animation/Survivor_MM_Pistol_Reload.Survivor_MM_Pistol_Reload" :SlotNodeName "PistolUpperBody" :BlendInTime 0.08 :BlendOutTime 0.12 :LoopCount 1)
  (else (Animation|Montage|StopSlotAnimation :self (Components|SkeletalMesh|GetAnimInstance (Variables|Character|GetMesh)) :SlotNodeName "PistolUpperBody" :InBlendOutTime 0.10))))''')
 write(bp,'CheckPistolEquip','''(fn CheckPistolEquip ()
 (bind Drawn (and (== (Variables|Default|GetPublicActiveSlot) 2) (== (Variables|Default|GetPublicSidearm) "Weapon.Pistol")))
 (if (and Drawn (not (Variables|Default|GetWasPistolDrawn)))
  (Animation|Montage|PlaySlotAnimationasDynamicMontage :self (Components|SkeletalMesh|GetAnimInstance (Variables|Character|GetMesh)) :Asset "/Game/AIExample/Combat/Animation/Survivor_MM_Pistol_Equip.Survivor_MM_Pistol_Equip" :SlotNodeName "PistolUpperBody" :BlendInTime 0.08 :BlendOutTime 0.12 :LoopCount 1)
  (Audio|PlaySoundatLocation :Sound "/Game/AIExample/Weapons/TheHouse/06_SFX/GunSFX/Pistol/SC_Equip_Gun.SC_Equip_Gun" :Location (Transformation|GetActorLocation) :AttenuationSettings "/Game/AIExample/Combat/SA_Pistol.SA_Pistol"))
 (if (and (not Drawn) (Variables|Default|GetWasPistolDrawn))
  (Animation|Montage|StopSlotAnimation :self (Components|SkeletalMesh|GetAnimInstance (Variables|Character|GetMesh)) :SlotNodeName "PistolUpperBody" :InBlendOutTime 0.12))
 (Variables|Default|SetWasPistolDrawn Drawn))''')
 write(bp,'OnRep_PublicShotSerial','(fn OnRep_PublicShotSerial () (CallFunction|PlayPistolShot))')
 write(bp,'OnRep_PublicReloading','(fn OnRep_PublicReloading () (CallFunction|RefreshPistolReload))')
 write(bp,'OnRep_PublicAiming','(fn OnRep_PublicAiming () (CallFunction|RefreshPistolAim))')
 write(bp,'RefreshWeaponVisuals','''(fn RefreshWeaponVisuals ()
 (CallFunction|UpdateWeaponVisual :Slot 0 :ID (Variables|Default|GetPublicPrimary) :Visual (Variables|Default|GetPrimaryVisual))
 (CallFunction|UpdateWeaponVisual :Slot 1 :ID (Variables|Default|GetPublicSecondary) :Visual (Variables|Default|GetSecondaryVisual))
 (CallFunction|UpdateWeaponVisual :Slot 2 :ID (Variables|Default|GetPublicSidearm) :Visual (Variables|Default|GetSidearmVisual))
 (CallFunction|CheckPistolEquip))''')
 B.compile_blueprint(bp)
 eg=B.get_graph(bp,'EventGraph')
 event=next(n for n in B.find_nodes(eg) if B._get_node_info(n).type_id=='AddEvent|EventBeginPlay')
 parent=next(n for n in B.find_nodes(eg) if isinstance(n,unreal.K2Node_CallParentFunction) and 'BeginPlay' in B._get_node_info(n).type_id)
 init=next((n for n in B.find_nodes(eg) if B._get_node_info(n).type_id=='CallFunction|InitializePistolAnimation'),None)
 if not init:init=B.create_node(eg,'CallFunction|InitializePistolAnimation',unreal.IntPoint(650,0))
 for node in [event,parent]:
  p=next(p for p in B._get_node_info(node).output_pins if p.name=='then')
  for target in list(p.connected_pins):B.break_pins(p.pin_id,target)
 B.connect_pins(pin(event,'then',True),pin(parent,'execute'));B.connect_pins(pin(parent,'then',True),pin(init,'execute'))
 save(bp)
 print('PISTOL_CHARACTER_COMBAT_READY')


